(lambda _: kAssert(kEq(kData("{\"name\": \"Alice\"}"), {"name": "Alice"})))(None)
(lambda _: kAssert(kEq(kData("[1, 2, 3]"), [1, 2, 3])))(None)
(lambda _: kAssert(kEq(kData("{\"user\": {\"name\": \"Bob\"}}").get("user").get("name"), "Bob")))(None)
(lambda _: kAssert(kEq(kData("{\"active\": true}").get("active"), True)))(None)
(lambda _: kAssert(kEq(kData("{\"count\": 42}").get("count"), 42)))(None)
(lambda _: kAssert(kEq(kData([1, 2, 3]), [1, 2, 3])))(None)
(lambda _: kAssert(kEq(kData({"x": 10}).get("x"), 10)))(None)
(lambda _: kAssertFails(lambda : kData("not valid json")))(None)
(lambda _: kAssert((kData(None) is None)))(None)
(lambda _: kAssertFails(lambda : kData("invalid")))(None)
